constexpr std::uint64_t Generation=83;
struct Ledgers {progress::WorkLedger canonical{recovery::v2::WorkerKind::DurablePrefix,32},notes{recovery::v2::WorkerKind::DurablePrefix,32},tom{recovery::v2::WorkerKind::DurablePrefix,32};progress::WorkLedger& panel(bool isTom){return isTom?tom:notes;}progress::WorkLedger& other(bool isTom){return isTom?notes:tom;}};
struct NoHardwareCalls final:spike::VendorCalls {unsigned calls{};bool acquire(spike::Pixels&)noexcept override{++calls;return false;}void region(spike::Rect,int,int,int)noexcept override{++calls;}void events()noexcept override{++calls;}};
progress::Snapshot snapshot(progress::WorkLedger& ledger){auto s=ledger.snapshot();CHECK(s.fault==progress::Fault::None&&s.health.accepted>=s.health.completed&&s.health.backlog==s.health.accepted-s.health.completed);if(s.health.backlog)CHECK(s.health.oldest.generation==Generation&&s.health.oldest.monotonic>0&&s.health.oldest.boottime>0);else CHECK(s.health.oldest==recovery::v2::ClockPair{});return s;}
void pump(ux::Shell& shell,Canvas& canvas){shell.tick();canvas.changes();CHECK(!shell.failed());}
void documentReady(ux::Shell& shell,Canvas& canvas,Ledgers& ledgers){until([&]{pump(shell,canvas);auto c=snapshot(ledgers.canonical);return shell.writable()&&!shell.styledInk()->status().busy&&!shell.unsaved()&&c.health.accepted==1&&c.health.completed==1;});CHECK(snapshot(ledgers.notes).health.accepted==0&&snapshot(ledgers.tom).health.accepted==0);}
void panelReady(ux::Shell& shell,Canvas& canvas,Ledgers& ledgers,bool isTom,bool writable=true){until([&]{pump(shell,canvas);auto s=snapshot(ledgers.panel(isTom));bool ready=isTom?(shell.tomPanel()&&shell.tomPanel()->active()&&shell.tomPanel()->revealReady()&&(!writable||shell.tomPanel()->writable())):(shell.notesPanel()&&shell.notesPanel()->active()&&shell.notesPanel()->view().ready&&shell.notesPanel()->canLeave()&&(!writable||shell.notesPanel()->writable()));return ready&&s.health.accepted==s.health.completed&&!s.health.backlog&&shell.unsaved()==0;});}

void openPanel(ux::Shell& shell,Canvas& canvas,Ledgers& ledgers,bool isTom,bool createNote){CHECK(shell.action(ux::Action::Show));canvas.changes();CHECK(uitest::menu(shell,isTom?ux::MenuTom:ux::MenuNotes));pump(shell,canvas);panelReady(shell,canvas,ledgers,isTom,isTom);auto first=snapshot(ledgers.panel(isTom));if(isTom){CHECK(first.health.accepted>=1);if(createNote)CHECK(first.health.accepted==2);}else CHECK(first.health.accepted==1);if(!isTom){CHECK(uitest::notes(shell,createNote?ib::notes::HubCreate:ib::notes::EntryBase));pump(shell,canvas);panelReady(shell,canvas,ledgers,false);}}
QJsonObject storedNote(const Path& features,const QString& id){product::Services services(features);for(auto value:services.notes()){auto note=value.toObject();if(note["id"]==id)return note;}throw std::runtime_error("tracked-note-missing");}
QJsonArray storedInk(const Path& root,const Path& features,const QJsonObject& binding,bool isTom){if(isTom){companion::TomStore store(root);return store.draft(binding["conversation"].toString(),binding["turn"].toString()).originalHandwriting;}return storedNote(features,binding["note"].toString())["strokes"].toArray();}
QJsonObject binding(ux::Shell& shell,bool isTom){if(isTom){auto view=shell.tomPanel()->view();return {{"conversation",view.thread},{"turn",view.turn},{"context",view.context}};}return {{"note",shell.notesPanel()->view().note["id"]}};}
void stroke(ux::Shell& shell,progress::WorkLedger& ledger,int y,std::uint64_t before){CHECK(shell.reserve());CHECK(shell.append({250,y,spike::Phase::Down,1,false}));CHECK(snapshot(ledger).health.accepted==before+1);CHECK(shell.append({300,y+30,spike::Phase::Move,2,false}));CHECK(shell.append({350,y+60,spike::Phase::Up,3,false}));CHECK(snapshot(ledger).health.accepted==before+1);}
void isolation(Ledgers& ledgers,bool isTom,recovery::v2::WorkerHealth canonical,recovery::v2::WorkerHealth other){CHECK(snapshot(ledgers.canonical).health==canonical&&snapshot(ledgers.other(isTom)).health==other);}
void blocked(ux::Shell& shell,Canvas& canvas,Ledgers& ledgers,bool isTom,const progress::Snapshot& expected,recovery::v2::WorkerHealth canonical,recovery::v2::WorkerHealth other){for(unsigned n=0;n<32;++n){shell.tick();canvas.changes();CHECK(snapshot(ledgers.panel(isTom)).health==expected.health);isolation(ledgers,isTom,canonical,other);}}
int partialChild(const Path& app,const Path& root,bool isTom){auto book=library::documents(root)[0];auto features=product::featureDirectory(root,book),docroot=library::documentRoot(root,book.id);Ledgers ledgers;ux::Shell shell(app,root,true,false,false,{&ledgers.canonical,Generation},{&ledgers.notes,Generation},{&ledgers.tom,Generation});Canvas canvas(shell);CHECK(shell.choose(0));canvas.ready();documentReady(shell,canvas,ledgers);openPanel(shell,canvas,ledgers,isTom,false);auto target=binding(shell,isTom);auto before=storedInk(root,features,target,isTom);auto settled=snapshot(ledgers.panel(isTom)),canonical=snapshot(ledgers.canonical),other=snapshot(ledgers.other(isTom));std::unique_ptr<product::Services> notesLease;std::unique_ptr<companion::TomStore> tomLease;if(isTom)tomLease=std::make_unique<companion::TomStore>(root);else notesLease=std::make_unique<product::Services>(features);int y=isTom?1700:1550; /* inside the compact note sheet's writing area */CHECK(shell.reserve());CHECK(shell.append({300,y,spike::Phase::Down,10,false}));CHECK(shell.append({400,y+50,spike::Phase::Move,11,false}));auto accepted=snapshot(ledgers.panel(isTom));CHECK(accepted.health.accepted==settled.health.accepted+1&&accepted.health.completed==settled.health.completed&&accepted.health.backlog==1);isolation(ledgers,isTom,canonical.health,other.health);
 NoHardwareCalls calls;spike::VendorDisplay vendor(calls);ux::Display display(vendor,shell);display.operationSink()->cancel();CHECK(snapshot(ledgers.panel(isTom)).health==accepted.health&&calls.calls==0);notesLease.reset();tomLease.reset();ux::Shell::Shutdown state;until([&]{state=shell.pollQuiesce();return state.drained;});auto done=snapshot(ledgers.panel(isTom));CHECK(done.health.accepted==accepted.health.accepted&&done.health.completed==accepted.health.accepted&&!done.health.backlog);CHECK(!state.saved&&state.failed&&shell.unsaved()==1&&!reader::readViewResume(docroot,3,{}).clean);isolation(ledgers,isTom,canonical.health,other.health);auto after=storedInk(root,features,target,isTom);CHECK(after.size()==before.size()+1&&after.last().toObject()["interrupted"]==true&&after.last().toObject()["points"].toArray().size()==2);for(int i=0;i<before.size();++i)CHECK(after[i]==before[i]);target["before"]=before;target["after"]=after;underlay::atomicFile(root/"panel-progress-interruption.json",QJsonDocument(target).toJson(QJsonDocument::Compact));for(unsigned n=0;n<12;++n){state=shell.pollQuiesce();CHECK(state.drained&&!state.saved&&state.failed&&!shell.finish(0)&&snapshot(ledgers.panel(isTom)).health==done.health);isolation(ledgers,isTom,canonical.health,other.health);}display.shutdown();CHECK(calls.calls==0);std::puts("PANEL_PARTIAL_EXISTING_TOKEN_DURABLE_LOGICAL_UNCLEAN");std::fflush(stdout);return 0;
}
