  QProcess child;child.setProgram(QString::fromStdString((sys/"usr/lib/ld-linux-aarch64.so.1").string()));child.setArguments({"--library-path",QString::fromStdString((sys/"usr/lib").string()),QString::fromUtf8(argv[0]),"--panel-progress-partial",QString::fromStdString(app.string()),QString::fromStdString(root.string()),isTom?"tom":"notes"});child.start();CHECK(child.waitForStarted(5000)&&child.waitForFinished(45000));auto out=child.readAllStandardOutput(),err=child.readAllStandardError();if(child.exitCode()!=78||!out.contains("PANEL_PARTIAL_EXISTING_TOKEN_DURABLE_LOGICAL_UNCLEAN")){std::cerr<<out.constData()<<err.constData();CHECK(false);}CHECK(child.exitStatus()==QProcess::NormalExit);auto interrupted=QJsonDocument::fromJson(underlay::readBounded(root/"panel-progress-interruption.json",1024*1024)).object();CHECK(interrupted["before"].toArray()==durable&&!reader::readViewResume(docroot,3,{}).clean);
  {Ledgers ledgers;ux::Shell shell(app,root,true,false,false,{&ledgers.canonical,Generation},{&ledgers.notes,Generation},{&ledgers.tom,Generation});Canvas canvas(shell);CHECK(shell.choose(0));canvas.ready();documentReady(shell,canvas,ledgers);openPanel(shell,canvas,ledgers,isTom,false);CHECK(binding(shell,isTom)==target&&storedInk(root,features,target,isTom)==interrupted["after"].toArray());if(isTom)CHECK(shell.tomPanel()->view().question=="Q"&&shell.tomPanel()->view().handwriting==interrupted["after"].toArray());else CHECK(shell.notesPanel()->view().note["text"]=="q"&&shell.notesPanel()->view().note["strokes"]==interrupted["after"]);CHECK(!reader::readViewResume(docroot,3,{}).clean);CHECK(shell.finish(5000)&&shell.unsaved()==0&&!snapshot(ledgers.panel(isTom)).health.backlog);}
